Local Instance asanreflect_fx : PropExec.FPState := PropExec.fx0.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Import ListNotations.
Open Scope Z_scope.

Import AX2K. Import AX2SK. Import APK. Import APSK.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Definition RES_hull_def (SEGS : list Segment) (A : APK.atable) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 2 "U4;A1;o6;Y6;00;A1;i5;#0;A2;i4;#1;#1;A2;k10;#0;A3;k11;#1;#1;r1;LSEGS;RA1;i0;i1;LA;Ri2;A3;i3;#2;Liv;R#2;A2;i7;A2;k8;A1;k9;r2;#3;A2;k8;A2;k12;#3;A2;k10;#0;A3;k13;#1;#1;r1;A1;k14;r2;A1;k15;r2;").

Lemma in_ivs_covered : forall z l, in_ivs z l = covered l z.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S4;A1;o6;Y6;00;A1;i5;#0;A2;i4;#1;#1;A2;k10;#0;A3;k11;#1;#1;r1;Lz;Ri16;Ll;RA1;i0;#2;cdA2;o17;i18;A3;k19;#2;Lc;R#2;A2;k20;A2;k21;#3;r3;A2;k22;r3;A2;k12;#3;A2;k10;#0;A3;k13;#1;#1;r1;r1;A3;i23;i18;A2;k24;r2;r1;A2;k25;r1;r2;").
Qed.

Lemma in_ivs_cons : forall z iv l,
  in_ivs z (iv :: l) = (((bv_unsigned (fst iv) <=? z) && (z <? bv_unsigned (fst iv) + bv_unsigned (snd iv))) || in_ivs z l)%bool.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S4;A1;o6;Y6;00;A1;i5;#0;A2;i4;#1;#1;A2;k10;#0;A3;k11;#1;#1;r2;Lz;Ri16;Liv;R#2;Ll;RA1;i0;#2;A2;o17;i18;A2;k26;A2;k20;A2;k21;#3;r3;A2;k22;r3;A2;k12;#3;A2;k10;#0;A3;k13;#1;#1;r2;A2;k24;r3;r1;").
Qed.

Lemma in_ivs_app : forall z l1 l2, in_ivs z (l1 ++ l2) = (in_ivs z l1 || in_ivs z l2)%bool.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S5;A1;o6;Y6;00;A1;i5;#0;A2;i4;#1;#1;A1;i0;#2;A2;k10;#0;A3;k11;#1;#1;r1;Lz;Ri16;Ll1;R#3;Ll2;R#3;cdA4;k27;#2;Liv;R#2;A2;k20;A2;k21;#4;r4;A2;k22;r4;A2;k12;#4;A2;k10;#0;A3;k13;#1;#1;r1;r2;r1;A3;i23;i18;A2;k24;r3;A3;k28;#2;r2;r1;A2;k26;A2;k24;r3;r2;A2;k24;r3;r1;").
Qed.

