Lemma kn_grant_filter_ok : forall E M M' k ms lo n,
  know_ok SEGS E M k -> maps_apart E ms lo n ->
  0 <= lo -> (lo + n <= img_lo A \/ img_hi A <= lo) -> lo + n <= utop E -> isp_facts E -> 0 < n ->
