  ivs_wf l -> lo <= hi ->
  covered (maps_subtract l lo hi) x = (covered l x && negb (in_rng lo hi x))%bool.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S4;A1;i5;A1;o6;Y6;00;A3;k162;r7;r6;r5;PP;RP~Ri16;i18;A3;i23;i16;A2;k111;r1;#1;A2;k111;Lx;Ri16;A2;k20;A1;r2;r1;A1;k100;A3;k184;r7;r6;r1;r7;Px;Ri16;A3;i23;i18;A2;k25;#1;r1;A2;k20;A2;k25;r7;r1;A1;k100;A3;k184;r6;r5;r1;Ll;RA1;i0;A2;i4;#0;#0;Llo;Ri16;Lhi;Ri16;Lx;Ri16;L~RA1;k161;r4;L~RA2;k8;r4;r3;A4;k73;#2;#3;A3;k73;A1;k161;A3;k162;r6;r5;r4;A2;i7;#2;#3;A5;k183;r6;r5;r4;r2;r1;r3;").
Qed.

Inductive slarm := SlE | SlF | SlG | SlM.

Definition sl_nn (s : slarm) : bool := ltac2:(Rpl.RP.run_k (rplG ()) 1 "U0;Ls;Ri994;m994;RNLs;Ri994;i18;r1;4;o71;o71;o30;o71;").
Definition sl_charge (s : slarm) : bool := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S0;Ls;Ri994;m994;RNLs;Ri994;i18;r1;4;o30;o71;o71;o30;").

Record slice_post (s : slarm) (addr n : word) (model model' : Model) : Prop := SP {
  sp_maps : vm_maps (m_vmmaps model') = vm_maps (m_vmmaps model);
  sp_res : vm_reserved (m_vmmaps model') = vm_reserved (m_vmmaps model);
  sp_noacc : vm_noaccess (m_vmmaps model') =
             (if sl_nn s then [(addr, n)] else [])
               ++ maps_subtract (vm_noaccess (m_vmmaps model)) (bv_unsigned addr) (bv_unsigned addr + bv_unsigned n);
  sp_lazy : m_vm_lazy model' =
            match s with
            | SlM => m_vm_lazy model
            | SlF => (addr, n) :: maps_subtract (m_vm_lazy model) (bv_unsigned addr) (bv_unsigned addr + bv_unsigned n)
            | _ => maps_subtract (m_vm_lazy model) (bv_unsigned addr) (bv_unsigned addr + bv_unsigned n)
            end;
  sp_mat : m_vm_materialized model' =
           match s with
           | SlM => m_vm_materialized model
           | _ => List.filter (page_outside_range (bv_unsigned addr) (bv_unsigned addr + bv_unsigned n)) (m_vm_materialized model)
           end;
  sp_limit : vm_limit (m_vmmaps model') = vm_limit (m_vmmaps model);
  sp_brk : vm_brk (m_vmmaps model') = vm_brk (m_vmmaps model);
  sp_sbrk : vm_start_brk (m_vmmaps model') = vm_start_brk (m_vmmaps model);
  sp_mbase : vm_mmap_base (m_vmmaps model') = vm_mmap_base (m_vmmaps model);
  sp_halted : m_halted model' = m_halted model;
  sp_fds : m_fds model' = m_fds model;
  sp_fs : m_fs model' = m_fs model;
  sp_tid : m_tid model' = m_tid model;
  sp_isp : vm_init_sp (m_vmmaps model') = vm_init_sp (m_vmmaps model)    }.

Definition slice_mem (s : slarm) (addr n : word) (FULL FULL' : word -> option byte) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 5 "S11;A1;o6;Y6;00;A1;i5;#0;Y3;0;A1;o6;#2;A1;i5;#3;A1;i204;#4;P~R#1;#5;A2;k10;#0;r1;A2;k10;#0;r5;A2;k12;#8;A2;k10;#0;r4;A1;r3;r2;Ls;Ri994;Laddr;R#1;Ln;R#1;LFULL;R#6;LFULL';R#6;A2;i7;Px;R#1;P~RA2;i93;A2;k35;#7;#8;A2;k8;#9;#7;A3;i23;#5;#10;A1;r4;r2;Px;R#1;P~RA2;i7;A2;k8;#8;#7;A2;k35;#7;#9;A3;i23;#5;#10;m18;RNL~Ri18;#5;A1;k995;r7;2;A1;o63;#4;A2;o205;#4;A2;k149;#3;o68;").

Record slice_hyps (E : env) (cs : acs) (R : bvmap 5 word) (FULL : word -> option byte) (model : Model)
       (s : slarm) (m : amap) (addr n : word) (nZ : Z) (model' : Model) (FULL' : word -> option byte) : Prop := SH_ {
  sh_C : CSOK E cs R FULL model;
  sh_m : In m (a_maps cs);
  sh_nf : is_fog m = false;
  sh_Un : bv_unsigned n = nZ;
  sh_pos : 0 < nZ;
  sh_nal : nZ mod 4096 = 0;
  sh_al : bv_unsigned addr mod 4096 = 0;
  sh_in1 : bv_unsigned (edenot E (am_base m)) <= bv_unsigned addr;
  sh_in2 : bv_unsigned addr + nZ <= bv_unsigned (edenot E (am_base m)) + bv_unsigned (edenot E (am_len m));
  sh_post : slice_post s addr n model model';
  sh_mem : slice_mem s addr n FULL FULL';
  sh_F : s = SlF -> am_kind m = KRWLAZY;
  sh_nF : s <> SlF -> am_kind m <> KRWLAZY }.

Section Slice.
  Variables (E : env) (cs : acs) (R : bvmap 5 word) (FULL : word -> option byte) (model : Model).
  Variables (s : slarm) (m : amap) (addr n : word) (nZ : Z) (model' : Model) (FULL' : word -> option byte).
  Hypothesis SH : slice_hyps E cs R FULL model s m addr n nZ model' FULL'.
  Let HC := sh_C _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let Hm := sh_m _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let Hnf := sh_nf _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let Un := sh_Un _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let HnZpos := sh_pos _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let HnZal := sh_nal _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let Hal := sh_al _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let Hin1 := sh_in1 _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let Hin2 := sh_in2 _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let SPo := sh_post _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let SM := sh_mem _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let HF := sh_F _ _ _ _ _ _ _ _ _ _ _ _ SH.
  Let HnF := sh_nF _ _ _ _ _ _ _ _ _ _ _ _ SH.

  Let lo := bv_unsigned addr.
  Let hi := bv_unsigned addr + nZ.

  Lemma sl_bounds : 0 < bv_unsigned (edenot E (am_len m)) /\ bv_unsigned (edenot E (am_base m)) mod 4096 = 0
                    /\ bv_unsigned (edenot E (am_len m)) mod 4096 = 0
                    /\ (bv_unsigned (edenot E (am_base m)) + bv_unsigned (edenot E (am_len m)) <= img_lo A
                        \/ img_hi A <= bv_unsigned (edenot E (am_base m)))
                    /\ bv_unsigned (edenot E (am_base m)) + bv_unsigned (edenot E (am_len m)) <= utop E.
  Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S12;Y6;00;A1;o6;#0;A1;i5;#1;A2;i4;#2;#2;A2;k10;#1;A3;k13;#2;#2;r1;A2;k10;#1;A3;k11;#2;#2;r1;A1;o147;Y12;000;A2;k12;#5;#4;Liv;R#3;A2;i7;A2;k35;o68;#4;A2;i7;A3;i23;i16;A2;k133;#5;#6;o68;A2;i7;A3;i23;i16;A2;k133;#4;#6;o68;A2;i7;A2;i93;A2;k8;#7;A1;k9;vA;A2;k8;A1;k14;vA;#5;A2;k8;#7;A1;k663;vE;A1;k115;A1;k113;vmodel;A3;i3;#3;#8;#9;Px;R#3;P~RA3;k32;#3;r1;#9;A1;#8;r2;EB;RA12;k996;vSEGS;vA;vLIMIT;vSINV;vargH;vFS0;vE;vcs;vR;vFULL;vmodel;vHC;#10;A6;k282;P~R#10;#11;P~R#11;#10;A3;k280;#3;#8;#9;r1;A2;k573;vE;vm;A7;k577;vE;A1;k642;vcs;#9;vm;A12;k767;vSEGS;vA;vLIMIT;vSINV;vargH;vFS0;vE;vcs;vR;vFULL;vmodel;vHC;vHm;vHnf;").
Qed.

  Lemma sl_lohi : (hi <= img_lo A \/ img_hi A <= lo) /\ hi <= utop E /\ lo < hi /\ hi <= 2 ^ 64 /\ lo mod 4096 = 0 /\ hi mod 4096 = 0.
  Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S130;Y6;00;A1;o6;#0;A2;k10;#1;A2;k243;vE;A1;k272;vm;A2;k35;o68;#2;A2;k10;#1;A2;k243;vE;A1;k270;vm;A1;o147;Y12;000;A2;k133;#4;#5;A3;i23;i16;#6;o68;A2;k133;#2;#5;A3;i23;i16;#8;o68;A2;k12;#4;#2;A1;k9;vA;A1;k14;vA;A2;i93;A2;k8;#10;#11;A2;k8;#12;#4;A1;k663;vE;A2;k8;#10;#14;A2;i7;#13;#15;A2;i7;#9;#16;A2;i7;#7;#17;Y1;0;A1;o147;#19;A1;o147;#0;A2;k146;#20;#21;A2;i7;A2;i93;A2;k8;vhi;#11;A2;k8;#12;vlo;A2;i7;A2;k8;vhi;#14;A2;i7;A2;k35;vlo;vhi;A2;i7;A2;k8;vhi;#22;A2;i7;A3;i23;i16;A2;k133;vlo;#5;o68;A3;i23;i16;A2;k133;vhi;#5;o68;A2;k10;#1;vaddr;A2;k12;#24;vnZ;A2;i93;A2;k8;#25;#11;A2;k8;#12;#24;A2;k8;#25;#14;A2;k35;#24;#25;A2;k8;#25;#22;A2;k133;#24;#5;A3;i23;i16;#30;o68;A2;k133;#25;#5;A3;i23;i16;#32;o68;A2;i7;#31;#33;A2;i7;#29;#34;A2;i7;#28;#35;A2;i7;#27;#36;A1;i5;#1;A2;k118;A2;i4;#38;#38;A1;k15;vSEGS;A1;k588;vA;A1;k117;#39;A1;k117;#40;A3;i23;i16;#41;#42;A4;k227;A3;i23;i217;#39;#40;#43;A12;k225;i217;i16;A1;i23;i217;k117;A1;i23;i16;Lx;Ri217;Ly;Ri217;A3;k233;A3;i23;i16;A1;k117;r2;A1;k117;r1;A3;i23;i217;r2;r1;A2;k234;r2;r1;#39;#41;A2;o17;i16;#41;#40;#42;A2;o17;i16;#42;vRES_len';A1;k123;#40;A2;k8;o68;#42;A1;k123;#39;A2;k8;o68;#41;A2;k203;#2;#5;A2;k8;o68;#5;P~RA2;k8;o68;#2;P~R#50;A2;k8;o68;#8;A2;k203;#12;#5;A2;k133;#12;#5;P~RA2;k8;o68;#12;P~R#50;A2;k8;o68;#53;A1;o147;Y5;0f;A2;k154;#20;#55;A2;k35;o68;#20;A2;k146;#20;#55;P~R#57;P~RA2;k8;o68;#55;A2;k35;o68;#58;A2;k8;o68;#20;LHa;R#60;L~Ri78;A3;k155;#20;#55;r2;PHa;R#60;P~Ri78;A2;k8;o68;#58;A2;k203;#4;#5;P~RA2;k8;o68;#4;P~R#50;A2;k8;o68;#6;A2;k203;#24;#5;P~RA2;k8;o68;#24;P~R#50;A2;k8;o68;#30;A2;k203;#11;#5;A2;k133;#11;#5;P~RA2;k8;o68;#11;P~R#50;A2;k8;o68;#68;A2;k203;vnZ;#5;A2;k133;vnZ;#5;P~RA2;k8;o68;vnZ;P~R#50;A2;k8;o68;#71;A2;o96;i16;N7;N4;A2;o96;i16;o98;N5;A2;o96;i16;#76;N1;A1;o44;i45;A1;i0;i45;A1;o48;i16;A2;o47;i16;r6;A2;o47;i16;r7;A4;o46;i16;#81;r7;#83;A1;i49;i16;A1;i51;i16;A2;o58;i16;Y3;4;A2;o58;i16;Y3;5;A3;o70;i16;#87;#88;Y1;1;A2;o58;i16;#90;Y2;0;A2;o58;i16;#92;A1;o63;i53;A2;o158;i16;o68;A7;o5